// Accepts a Tally webhook payload (data.fields[]) or a flat JSON body for testing.
const body = $('Tally Form Webhook').first().json.body ?? {};
const raw = {};
if (Array.isArray(body?.data?.fields)) {
  for (const f of body.data.fields) {
    let v = f.value;
    if (Array.isArray(v) && f.options) v = v.map(id => (f.options.find(o => o.id === id) || {}).text || id).join(', ');
    else if (Array.isArray(v)) v = v.join(', ');
    raw[(f.label || f.key || '').toLowerCase().trim()] = v ?? '';
  }
} else Object.assign(raw, body);

const pick = (...keys) => {
  for (const k of keys) for (const [label, v] of Object.entries(raw))
    if (label.includes(k) && v !== '' && v != null) return String(v).trim();
  return '';
};

const brief = {
  business_name:   pick('business', 'company', 'brand'),
  contact_name:    pick('your name', 'contact', 'name'),
  contact_email:   pick('email'),
  website:         pick('website', 'url'),
  industry:        pick('industry', 'niche', 'sector'),
  country:         pick('country', 'market', 'location'),
  offer:           pick('product', 'service', 'offer'),
  target_audience: pick('audience', 'customer'),
  goals:           pick('goal', 'objective'),
  budget:          pick('budget'),
  competitors:     pick('competitor'),
  brand_tone:      pick('tone', 'voice', 'personality'),
  notes:           pick('note', 'anything else', 'additional'),
};
if (!brief.business_name || !brief.contact_email)
  throw new Error('Form is missing business name or contact email');

brief.client_id = 'CL-' + $now.toFormat('yyyyLLdd-HHmmss');
brief.submitted_at = $now.toISO();
brief.brief_text = Object.entries(brief)
  .filter(([k, v]) => v && !['client_id', 'submitted_at'].includes(k))
  .map(([k, v]) => `- ${k.replace(/_/g, ' ')}: ${v}`).join('\n');
return [{ json: brief }];

const fmt = (node) => {
  const r = $(node).first().json;
  const lines = (r.results || []).map((x, i) => `${i + 1}. ${x.title}\n   ${x.url}\n   ${(x.content || '').slice(0, 500)}`);
  return `Summary: ${r.answer || 'n/a'}\n${lines.join('\n')}`;
};
return [{ json: {
  market_research: fmt('Tavily: Market'),
  competitor_research: fmt('Tavily: Competitors'),
  audience_research: fmt('Tavily: Audience'),
} }];

